import java.util.*;
import java.io.*;

public class Main {
    static int[] lexicalTopoOrder(int n, int[][] edges) {
        // Write your solution here
        // Return new int[]{-1} if the graph contains a cycle.
        return new int[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        int[][] edges = new int[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken(); edges[i][0] = (int) in.nval;
            in.nextToken(); edges[i][1] = (int) in.nval;
        }
        int[] order = lexicalTopoOrder(n, edges);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < order.length; i++) sb.append(order[i]).append(i + 1 < order.length ? " " : "\n");
        System.out.print(sb);
    }
}
